import { Component, input } from '@angular/core';

/** hrm-table-toolbar — thanh công cụ TRÊN bảng: trái = tiêu đề + số đếm (hoặc slot [tbTitle]),
 *  giữa = slot mặc định (ô tìm kiếm / bộ lọc, tự giãn), phải = slot [tbActions] (nút Thêm/Xuất…).
 *  Không viền ngoài — đặt trong thẻ/section sẵn có; divided = kẻ mảnh dưới toolbar.
 *  i18n-clean: title/countLabel do bên gọi cấp. */
@Component({
  selector: 'hrm-table-toolbar',
  template: `
    <div class="tb-left">
      <ng-content select="[tbTitle]" />
      @if (title()) { <span class="tb-title">{{ title() }}</span> }
      @if (count() !== null) {
        <span class="tb-count">{{ count() }}@if (countLabel()) {&ngsp;{{ countLabel() }}}</span>
      }
    </div>
    <div class="tb-mid"><ng-content /></div>
    <div class="tb-right"><ng-content select="[tbActions]" /></div>
  `,
  host: { class: 'hrm-table-toolbar', '[class.hrm-table-toolbar--divided]': 'divided()' },
  styles: [`
:host { display: flex; align-items: center; gap: 12px; padding: 8px 12px; min-width: 0; }
:host(.hrm-table-toolbar--divided) { border-bottom: 1px solid var(--border-soft); margin-bottom: 12px; }

.tb-left { display: flex; align-items: center; gap: 8px; flex: none; min-width: 0; }
/* Không title/count/[tbTitle] → ẩn hẳn để KHÔNG chiếm gap 12px của host (tránh đẩy search sang phải). */
.tb-left:empty { display: none; }
.tb-title { font-size: var(--fs-15); font-weight: 600; color: var(--text-strong); white-space: nowrap; }
.tb-count {
  font-size: var(--fs-12); color: var(--text-sub); background: var(--bg-surface-subtle);
  padding: 1px 8px; border-radius: var(--radius-full); white-space: nowrap;
}

.tb-mid { flex: 1; display: flex; align-items: center; gap: 8px; min-width: 0; }
.tb-right { flex: none; display: flex; align-items: center; gap: 8px; }
  `],
})
export class HrmTableToolbar {
  /** Tiêu đề bảng (bỏ trống nếu dùng slot [tbTitle]). */
  readonly title = input('');
  /** Số bản ghi — null = ẩn. */
  readonly count = input<number | null>(null);
  /** Nhãn sau số đếm (VD "nhân viên") — bên gọi cấp (i18n). */
  readonly countLabel = input('');
  /** Kẻ mảnh dưới toolbar. */
  readonly divided = input(false);
}
