import { ChangeDetectionStrategy, Component, ViewEncapsulation, computed, effect, input, model, output, signal } from '@angular/core';
import { CdkDropList, CdkDrag, CdkDragHandle, CdkDragDrop, moveItemInArray } from '@angular/cdk/drag-drop';
import { TablerIconComponent, IconGripVertical, IconTrash, IconPlus, IconX, IconArrowUp, IconArrowDown, IconArrowsSort, IconChevronDown } from '@tabler/icons-angular';
import { HrmGridSort, SortDir } from './hrm-grid';

/** Cột chọn được trong dialog sắp xếp (chỉ cần key + nhãn). */
export interface HrmSortColumn { key: string; title: string; }

/**
 * hrm-sort-config — hộp thoại "Cấu hình sắp xếp" ĐA CẤP (theo ảnh thiết kế).
 *  - Mỗi cấp: [grip ⠿ đầu dòng để KÉO đổi ưu tiên] · chọn cột · [Tăng|Giảm] · [thùng rác xoá].
 *    (grip thay cho nút ↑↓; thùng rác thay cho dấu ✕.)
 *  - Sửa trên BẢN NHÁP; "Áp dụng" mới ghi vào levels (two-way) + phát applied; "Huỷ" bỏ nháp.
 *  - Nhiều cấp = sort đa khóa: cấp trên hoà nhau mới xét cấp dưới.
 *
 * <hrm-sort-config [(open)]="sortOpen" [columns]="sortableCols" [(levels)]="sortLevels" />
 */
@Component({
  selector: 'hrm-sort-config',
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  imports: [CdkDropList, CdkDrag, CdkDragHandle, TablerIconComponent],
  template: `
    @if (open()) {
      <div class="sc-ov">
        <div class="sc-bd" (click)="cancel()"></div>
        <div class="sc-dlg" role="dialog" aria-modal="true" [attr.aria-label]="title()">
          <header class="sc-hd">
            <span class="sc-t"><tabler-icon [icon]="icSort" [size]="18" /> {{ title() }}</span>
            <button type="button" class="sc-x" [attr.aria-label]="closeLabel()" (click)="cancel()"><tabler-icon [icon]="icX" [size]="18" /></button>
          </header>
          <p class="sc-sub">{{ subtitle() }}</p>

          @if (!draft().length) {
            <div class="sc-empty">{{ emptyText() }}</div>
          } @else {
            <div class="sc-list" cdkDropList (cdkDropListDropped)="onDrop($event)">
              @for (lv of draft(); track $index; let i = $index) {
                <div class="sc-row" cdkDrag>
                  <span class="sc-grip" cdkDragHandle [attr.aria-label]="reorderLabel()"><tabler-icon [icon]="icGrip" [size]="16" /></span>
                  <span class="sc-lead">{{ i === 0 ? byLabel() : thenLabel() }}</span>
                  <div class="sc-sel">
                    <select (change)="setKey(i, $any($event.target).value)" [attr.aria-label]="byLabel()">
                      @for (c of columns(); track c.key) { <option [value]="c.key" [selected]="c.key === lv.key">{{ c.title }}</option> }
                    </select>
                    <tabler-icon class="sc-sel-ic" [icon]="icChevron" [size]="16" />
                  </div>
                  <div class="sc-dir" role="group" [attr.aria-label]="byLabel()">
                    <button type="button" [class.on]="lv.dir === 'asc'" (click)="setDir(i, 'asc')"><tabler-icon [icon]="icUp" [size]="14" /> {{ ascLabel() }}</button>
                    <button type="button" [class.on]="lv.dir === 'desc'" (click)="setDir(i, 'desc')"><tabler-icon [icon]="icDown" [size]="14" /> {{ descLabel() }}</button>
                  </div>
                  <button type="button" class="sc-del" [attr.aria-label]="removeLabel()" (click)="remove(i)"><tabler-icon [icon]="icTrash" [size]="16" /></button>
                </div>
              }
            </div>
          }

          <button type="button" class="sc-add" [disabled]="!canAdd()" (click)="add()">
            <tabler-icon [icon]="icPlus" [size]="15" /> {{ addLabel() }}
          </button>

          <footer class="sc-ft">
            <button type="button" class="sc-clear" (click)="clearAll()">{{ clearLabel() }}</button>
            <span class="sc-sp"></span>
            <button type="button" class="sc-btn" (click)="cancel()">{{ cancelLabel() }}</button>
            <button type="button" class="sc-btn is-primary" (click)="apply()">{{ applyLabel() }}</button>
          </footer>
        </div>
      </div>
    }
  `,
  styles: [`
.sc-ov { position: fixed; inset: 0; z-index: 1000; display: grid; place-items: center; padding: 24px; }
.sc-bd { position: absolute; inset: 0; background: var(--overlay-bg, rgba(0,0,0,.45)); }
.sc-dlg { position: relative; width: 100%; max-width: 560px; background: var(--bg-surface);
  border: 1px solid var(--border-sub); border-radius: var(--radius-xl, 12px); box-shadow: var(--shadow-regular-lg);
  font-family: var(--font-sans); display: flex; flex-direction: column; max-height: 88vh; }
.sc-hd { display: flex; align-items: center; gap: 8px; padding: 14px 16px 0; }
.sc-t { display: flex; align-items: center; gap: 8px; font-size: var(--fs-16, 16px); font-weight: var(--font-semibold, 600); color: var(--text-strong); }
.sc-x { margin-inline-start: auto; display: grid; place-items: center; width: 30px; height: 30px; border: 0; background: transparent;
  border-radius: var(--radius-md, 8px); color: var(--text-soft); cursor: pointer; }
.sc-x:hover { background: var(--bg-surface-subtle); color: var(--text-strong); }
.sc-sub { margin: 6px 16px 14px; font-size: var(--fs-13, 13px); color: var(--text-sub); }

.sc-empty { margin: 0 16px; padding: 28px 16px; text-align: center; font-size: var(--fs-13, 13px); color: var(--text-soft);
  border: 1px dashed var(--border-sub); border-radius: var(--radius-lg, 10px); }

.sc-list { display: flex; flex-direction: column; gap: 8px; padding: 0 16px; overflow-y: auto; }
.sc-row { display: flex; align-items: center; gap: 8px; background: var(--bg-surface); }
.sc-grip { flex: none; display: inline-grid; place-items: center; width: 22px; height: 34px; color: var(--text-soft); cursor: grab; border-radius: var(--radius-sm, 6px); }
.sc-grip:hover { background: var(--bg-surface-subtle); color: var(--text-body); }
.sc-grip:active { cursor: grabbing; }
.sc-lead { flex: none; width: 64px; font-size: var(--fs-13, 13px); color: var(--text-soft); }
.sc-sel { position: relative; flex: 1; min-width: 0; }
.sc-sel select { width: 100%; height: 36px; padding: 0 30px 0 10px; border: 1px solid var(--border-sub); border-radius: var(--radius-md, 8px);
  background: var(--bg-surface); color: var(--text-body); font: inherit; font-size: var(--fs-14, 14px); cursor: pointer;
  appearance: none; -webkit-appearance: none; }
.sc-sel select:focus-visible { outline: 2px solid var(--primary-focus-ring, var(--primary-base)); outline-offset: 1px; border-color: var(--primary-base); }
.sc-sel-ic { position: absolute; inset-inline-end: 8px; top: 50%; transform: translateY(-50%); color: var(--text-soft); pointer-events: none; }
.sc-dir { flex: none; display: inline-flex; border: 1px solid var(--border-sub); border-radius: var(--radius-md, 8px); overflow: hidden; }
.sc-dir button { display: inline-flex; align-items: center; gap: 4px; height: 34px; padding: 0 10px; border: 0; background: transparent;
  color: var(--text-sub); font: inherit; font-size: var(--fs-13, 13px); cursor: pointer; }
.sc-dir button + button { border-inline-start: 1px solid var(--border-sub); }
.sc-dir button.on { background: var(--primary-bg-subtle); color: var(--primary-base); font-weight: var(--font-medium, 500); }
.sc-del { flex: none; display: grid; place-items: center; width: 34px; height: 34px; border: 0; background: transparent;
  border-radius: var(--radius-md, 8px); color: var(--text-soft); cursor: pointer; }
.sc-del:hover { background: var(--error-bg); color: var(--error-base); }

.sc-add { margin: 12px 16px 4px; display: inline-flex; align-items: center; justify-content: center; gap: 6px; height: 40px;
  border: 1px dashed var(--border-sub); border-radius: var(--radius-md, 8px); background: transparent; color: var(--text-sub);
  font: inherit; font-size: var(--fs-14, 14px); cursor: pointer; }
.sc-add:hover:not(:disabled) { border-color: var(--primary-border); color: var(--text-strong); }
.sc-add:disabled { opacity: .5; cursor: not-allowed; }

.sc-ft { display: flex; align-items: center; gap: 8px; padding: 12px 16px; margin-top: 8px; border-top: 1px solid var(--border-soft); }
.sc-sp { flex: 1; }
.sc-clear { border: 0; background: transparent; color: var(--text-sub); font: inherit; font-size: var(--fs-14, 14px); cursor: pointer; padding: 6px 4px; }
.sc-clear:hover { color: var(--text-strong); }
.sc-btn { height: 36px; padding: 0 14px; border: 1px solid var(--border-sub); border-radius: var(--radius-md, 8px);
  background: var(--bg-surface); color: var(--text-body); font: inherit; font-size: var(--fs-14, 14px); cursor: pointer; }
.sc-btn:hover { background: var(--bg-surface-subtle); }
.sc-btn.is-primary { background: var(--primary-base); color: var(--text-on-primary); border-color: var(--primary-base); }
.sc-btn.is-primary:hover { background: var(--primary-strong, var(--primary-base)); }
.sc-btn:focus-visible, .sc-clear:focus-visible { outline: 2px solid var(--primary-focus-ring, var(--primary-base)); outline-offset: 1px; }

.cdk-drag-preview .sc-row, .sc-row.cdk-drag-preview { box-shadow: var(--shadow-regular-md); border-radius: var(--radius-md, 8px); }
.cdk-drag-placeholder { opacity: .4; }
  `],
})
export class HrmSortConfig {
  /** Hiển thị dialog (two-way). */
  readonly open = model(false);
  /** Danh sách cột chọn được (key + nhãn). */
  readonly columns = input<HrmSortColumn[]>([]);
  /** Cấu hình sort đang áp (two-way) — chỉ ghi khi bấm "Áp dụng". */
  readonly levels = model<HrmGridSort[]>([]);
  /** Phát khi bấm Áp dụng (kèm danh sách cấp mới). */
  readonly applied = output<HrmGridSort[]>();

  /** Nhãn i18n (mặc định tiếng Việt). */
  readonly title = input('Cấu hình sắp xếp');
  readonly subtitle = input('Xếp theo nhiều cấp ưu tiên; cấp trên hoà nhau mới xét cấp dưới.');
  readonly emptyText = input('Chưa có cấp sắp xếp nào. Thêm một cấp để bắt đầu.');
  readonly byLabel = input('Xếp theo');
  readonly thenLabel = input('rồi theo');
  readonly ascLabel = input('Tăng');
  readonly descLabel = input('Giảm');
  readonly addLabel = input('Thêm cấp sắp xếp');
  readonly clearLabel = input('Xoá hết');
  readonly cancelLabel = input('Huỷ');
  readonly applyLabel = input('Áp dụng');
  readonly closeLabel = input('Đóng');
  readonly reorderLabel = input('Kéo đổi thứ tự ưu tiên');
  readonly removeLabel = input('Xoá cấp');

  protected readonly icSort = IconArrowsSort;
  protected readonly icX = IconX;
  protected readonly icGrip = IconGripVertical;
  protected readonly icTrash = IconTrash;
  protected readonly icPlus = IconPlus;
  protected readonly icUp = IconArrowUp;
  protected readonly icDown = IconArrowDown;
  protected readonly icChevron = IconChevronDown;

  /** Bản nháp đang sửa — clone từ levels() KHI MỞ; sửa nội bộ, không đụng levels cho tới khi Áp dụng. */
  protected readonly draft = signal<HrmGridSort[]>([]);
  /** Theo dõi mở/đóng để chỉ clone lại nháp đúng lúc false→true (không reset giữa chừng khi đang sửa). */
  private wasOpen = false;

  constructor() {
    effect(() => {
      const o = this.open();
      if (o && !this.wasOpen) this.draft.set(this.levels().map((l) => ({ ...l })));
      this.wasOpen = o;
    });
  }

  /** Còn cột chưa dùng để thêm cấp. */
  protected readonly canAdd = computed(() => this.draft().length < this.columns().length);

  protected setKey(i: number, key: string): void {
    const next = this.draft().map((l, j) => (j === i ? { ...l, key } : l));
    this.draft.set(next);
  }
  protected setDir(i: number, dir: SortDir): void {
    const next = this.draft().map((l, j) => (j === i ? { ...l, dir } : l));
    this.draft.set(next);
  }
  protected remove(i: number): void { this.draft.set(this.draft().filter((_, j) => j !== i)); }
  protected clearAll(): void { this.draft.set([]); }
  protected add(): void {
    this.draft.update((cur) => {
      const used = new Set(cur.map((l) => l.key));
      const first = this.columns().find((c) => !used.has(c.key));
      return first ? [...cur, { key: first.key, dir: 'asc' as SortDir }] : cur;
    });
  }
  protected onDrop(e: CdkDragDrop<unknown>): void {
    const arr = [...this.draft()];
    moveItemInArray(arr, e.previousIndex, e.currentIndex);
    this.draft.set(arr);
  }
  protected cancel(): void { this.open.set(false); }
  protected apply(): void {
    const clean = this.draft().map((l) => ({ ...l }));
    this.levels.set(clean);
    this.applied.emit(clean);
    this.open.set(false);
  }
}
