import { ChangeDetectionStrategy, Component, ViewEncapsulation, computed, input, model, output } from '@angular/core';
import { NzDropDownModule } from 'ng-zorro-antd/dropdown';
import { NzMenuModule } from 'ng-zorro-antd/menu';
import {
  TablerIconComponent, IconSearch, IconFilter, IconArrowsSort, IconColumns, IconDownload, IconX, IconEye, IconEyeOff,
} from '@tabler/icons-angular';
import { HrmSortConfig, HrmSortColumn } from './hrm-sort-config';
import { HrmGridSort } from './hrm-grid';

/**
 * hrm-data-toolbar — thanh công cụ DÙNG CHUNG trên bảng / kanban / card (theo template "Chế độ dữ liệu").
 *  Trái: ô tìm kiếm (phát searchChange) · nút Bộ lọc (phát filterClick) · slot [tbFilters].
 *  Phải: nút Sắp xếp (mở hrm-sort-config đa cấp — two-way sortLevels) · nút Cột (ẩn/hiện — two-way hiddenKeys) ·
 *        nút Xuất (phát exportClick) · slot [tbActions] · slot [tbMore] (⋮).
 *
 *  KHÔNG ôm nghiệp vụ lọc/xuất/tìm — chỉ phát event; consumer (hoặc hrm-data-view) tự xử + nối state với grid.
 *  Sort/Cột nối grid qua CHUNG signal: <hrm-grid [(sortLevels)]="s" [(hiddenKeys)]="h"> + <hrm-data-toolbar [(sortLevels)]="s" [(hiddenKeys)]="h">.
 */
@Component({
  selector: 'hrm-data-toolbar',
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  imports: [NzDropDownModule, NzMenuModule, TablerIconComponent, HrmSortConfig],
  template: `
    <div class="dt-bar">
      @if (searchable()) {
        <label class="dt-search">
          <tabler-icon class="dt-search-ic" [icon]="icSearch" [size]="16" />
          <input type="search" [value]="search()" [placeholder]="searchPlaceholder()"
            [attr.aria-label]="searchPlaceholder()" (input)="onSearch($any($event.target).value)" />
          @if (search()) {
            <button type="button" class="dt-search-clr" [attr.aria-label]="clearLabel()" (click)="onSearch('')"><tabler-icon [icon]="icX" [size]="14" /></button>
          }
        </label>
      }
      @if (filterable()) {
        <button type="button" class="dt-btn" (click)="filterClick.emit()">
          <tabler-icon [icon]="icFilter" [size]="16" /> <span>{{ filterLabel() }}</span>
          @if (filterCount() > 0) { <span class="dt-n">{{ filterCount() }}</span> }
        </button>
      }
      <ng-content select="[tbFilters]" />

      <span class="dt-sp"></span>

      @if (count() !== null) { <span class="dt-count">{{ count() }}@if (countLabel()) {&ngsp;{{ countLabel() }}}</span> }

      @if (sortColumns().length) {
        <button type="button" class="dt-btn" (click)="sortOpen.set(true)">
          <tabler-icon [icon]="icSort" [size]="16" /> <span>{{ sortLabel() }}</span>
          @if (sortLevels().length) { <span class="dt-n">{{ sortLevels().length }}</span> }
        </button>
      }
      @if (columns().length) {
        <button type="button" class="dt-btn" nz-dropdown [nzDropdownMenu]="colsMenu" nzTrigger="click" [attr.aria-label]="columnsLabel()">
          <tabler-icon [icon]="icColumns" [size]="16" /> <span>{{ columnsLabel() }}</span>
          @if (hiddenKeys().length) { <span class="dt-n">{{ hiddenKeys().length }}</span> }
        </button>
        <nz-dropdown-menu #colsMenu="nzDropdownMenu">
          <ul nz-menu class="dt-menu">
            @for (c of columns(); track c.key) {
              <li nz-menu-item (click)="toggleCol(c.key, $event)">
                <tabler-icon [icon]="isHidden(c.key) ? icEyeOff : icEye" [size]="16" [class.dt-off]="isHidden(c.key)" />
                <span>{{ c.title }}</span>
              </li>
            }
            <li nz-menu-divider></li>
            <li nz-menu-item (click)="showAll()"><span>{{ showAllLabel() }}</span></li>
          </ul>
        </nz-dropdown-menu>
      }
      @if (exportable()) {
        <button type="button" class="dt-btn" (click)="exportClick.emit()">
          <tabler-icon [icon]="icExport" [size]="16" /> <span>{{ exportLabel() }}</span>
        </button>
      }
      <ng-content select="[tbActions]" />
      <ng-content select="[tbMore]" />
    </div>

    <hrm-sort-config [(open)]="sortOpen" [columns]="sortColumns()" [(levels)]="sortLevels" />
  `,
  host: { class: 'hrm-data-toolbar' },
  styles: [`
.dt-bar { display: flex; align-items: center; gap: 8px; min-width: 0; flex-wrap: wrap; }
.dt-sp { flex: 1 1 0; min-width: 0; }
.dt-count { font-size: var(--fs-12, 12px); color: var(--text-sub); background: var(--bg-surface-subtle);
  padding: 2px 10px; border-radius: var(--radius-full); white-space: nowrap; }

.dt-search { display: flex; align-items: center; gap: 8px; flex: 1 1 180px; min-width: 140px; max-width: 420px; height: 38px;
  padding: 0 10px; background: var(--bg-surface); border: 1px solid var(--border-sub); border-radius: var(--radius-lg, 10px); }
.dt-search:focus-within { border-color: var(--primary-base); }
.dt-search-ic { flex: none; color: var(--text-soft); }
.dt-search input { flex: 1; min-width: 0; border: 0; background: transparent; outline: none; font: inherit;
  font-size: var(--fs-14, 14px); color: var(--text-body); }
.dt-search input::placeholder { color: var(--text-soft); }
.dt-search input::-webkit-search-cancel-button { display: none; }
.dt-search-clr { flex: none; display: grid; place-items: center; width: 18px; height: 18px; border: 0; background: transparent;
  color: var(--text-soft); cursor: pointer; border-radius: var(--radius-sm, 6px); }
.dt-search-clr:hover { color: var(--text-strong); background: var(--bg-surface-subtle); }

.dt-btn { display: inline-flex; align-items: center; gap: 6px; height: 38px; padding: 0 12px; flex: none;
  border: 1px solid var(--border-sub); background: var(--bg-surface); border-radius: var(--radius-md, 8px);
  color: var(--text-body); font: inherit; font-size: var(--fs-14, 14px); cursor: pointer; white-space: nowrap;
  transition: border-color var(--duration-fast, .15s) var(--ease-out, ease), background var(--duration-fast, .15s) var(--ease-out, ease); }
.dt-btn:hover { border-color: var(--primary-border); color: var(--text-strong); }
.dt-btn:focus-visible { outline: 2px solid var(--primary-focus-ring, var(--primary-base)); outline-offset: 1px; }
.dt-n { display: inline-grid; place-items: center; min-width: 18px; height: 18px; padding: 0 5px;
  border-radius: var(--radius-full); background: var(--primary-bg-soft); color: var(--primary-base);
  font-size: var(--fs-11, 11px); font-weight: var(--font-semibold, 600); line-height: 1; }

:host ::ng-deep .dt-menu li[nz-menu-item] { display: flex; align-items: center; gap: 8px; }
:host ::ng-deep .dt-menu .dt-off { opacity: .5; }
  `],
})
export class HrmDataToolbar {
  /** Số bản ghi (null = ẩn). */
  readonly count = input<number | null>(null);
  readonly countLabel = input('');

  /** Ô tìm kiếm dựng sẵn — phát searchChange; consumer tự lọc data. */
  readonly searchable = input(true);
  readonly search = model('');
  readonly searchPlaceholder = input('Tìm kiếm…');
  readonly searchChange = output<string>();

  /** Nút Bộ lọc — chỉ phát filterClick (consumer mở panel lọc riêng). */
  readonly filterable = input(false);
  readonly filterCount = input(0);
  readonly filterClick = output<void>();

  /** Nút Xuất — chỉ phát exportClick. */
  readonly exportable = input(false);
  readonly exportClick = output<void>();

  /** Sắp xếp đa cấp: cột chọn được + cấu hình (two-way, nối chung với grid). */
  readonly sortColumns = input<HrmSortColumn[]>([]);
  readonly sortLevels = model<HrmGridSort[]>([]);

  /** Ẩn/hiện cột: toàn bộ cột + khóa đang ẩn (two-way, nối chung với grid). */
  readonly columns = input<HrmSortColumn[]>([]);
  readonly hiddenKeys = model<string[]>([]);

  /** Nhãn i18n (mặc định tiếng Việt). */
  readonly filterLabel = input('Bộ lọc');
  readonly sortLabel = input('Sắp xếp');
  readonly columnsLabel = input('Cột');
  readonly exportLabel = input('Xuất dữ liệu');
  readonly showAllLabel = input('Hiện tất cả');
  readonly clearLabel = input('Xoá');

  protected readonly sortOpen = model(false);

  protected readonly icSearch = IconSearch;
  protected readonly icFilter = IconFilter;
  protected readonly icSort = IconArrowsSort;
  protected readonly icColumns = IconColumns;
  protected readonly icExport = IconDownload;
  protected readonly icX = IconX;
  protected readonly icEye = IconEye;
  protected readonly icEyeOff = IconEyeOff;

  protected readonly hiddenSet = computed(() => new Set(this.hiddenKeys()));
  protected isHidden(key: string): boolean { return this.hiddenSet().has(key); }

  protected onSearch(v: string): void { this.search.set(v); this.searchChange.emit(v); }
  protected toggleCol(key: string, e?: Event): void {
    e?.stopPropagation();
    this.hiddenKeys.update((a) => (a.includes(key) ? a.filter((k) => k !== key) : [...a, key]));
  }
  protected showAll(): void { this.hiddenKeys.set([]); }
}
